  .info h3:after{ content:""; display:block; width:28px;height:3px;background:#f07d86; margin-top:8px; border-radius:3px; }
  .info p{ line-height:1.6; color:#4a4a4a; }

  /* Toast */
  .toast{
    position:fixed; left:50%; transform:translateX(-50%);
    bottom:18px; width:calc(644px - 36px);
    background:#fff; color:#333; border-radius:12px; padding:14px; display:flex; align-items:center; justify-content:space-between;
    box-shadow:0 10px 30px rgba(0,0,0,.35); opacity:0; pointer-events:none; transition:opacity .3s ease;
  }
  .toast.show{ opacity:1; pointer-events:auto; }
  .toast .cta{ background:#3aaa72; color:#fff; border:none; border-radius:8px; padding:10px 14px; font-weight:700; }

  /* Confetti */
  .confetti-area{ position:absolute; left:0; right:0; pointer-events:none; top:410px; height:220px; overflow:visible; }
  .confetti{ position:absolute; width:8px; height:14px; opacity:0; transform:translateY(-40px) rotate(0deg); }
  @keyframes drop {
    0%{ transform:translateY(-30px) rotate(0deg); opacity:1; }
    100%{ transform:translateY(240px) rotate(360deg); opacity:0; }
  }

  /* Reusable */
  .btn{ cursor:pointer; }
</style>
</head>
<body>
<div id="app" class="app">
  <header>
    <div class="brand">
