<script>
(function(){
  const app = document.getElementById('app');

  const MODES = {
    pomo:  { name:'Pomodoro', secs:25*60, theme:'theme-pomo', colors:{bg:'#b03844', panel:'#bd535d'} },
    short: { name:'Short Break', secs:5*60,  theme:'theme-short', colors:{bg:'#7b5a61', panel:'#8c6b72'} },
    long:  { name:'Long Break', secs:15*60, theme:'theme-long',  colors:{bg:'#2e8e88', panel:'#3e9f98'} }
  };

  let state = {
    mode:'pomo',
    remaining: MODES.pomo.secs,
    running:false,
    timer:null,
    tasks:[],      // {id,title,est,done:false,doneCount:0}
    counter:0
  };

  const timeEl = document.getElementById('time');
  const startBtn = document.getElementById('startBtn');
  const skipBtn = document.getElementById('skipBtn');
  const nowLine = document.getElementById('nowLine');
  const nowTitle = document.getElementById('nowTitle');
  const tabs = document.querySelectorAll('.tab');
  const addBox = document.getElementById('addBox');
  const addBoxBottom = document.getElementById('addBoxBottom');
  const addCard = document.getElementById('addCard');
  const cancelAdd = document.getElementById('cancelAdd');
  const saveTask = document.getElementById('saveTask');
  const estVal = document.getElementById('estVal');
  const estUp = document.getElementById('estUp');
  const estDown = document.getElementById('estDown');
  const titleInput = document.getElementById('taskTitle');
  const list = document.getElementById('taskList');
  const summary = document.getElementById('summary');
  const pomoCount = document.getElementById('pomoCount');
  const finishAt = document.getElementById('finishAt');
  const toast = document.getElementById('toast');
  const confettiArea = document.getElementById('confettiArea');
  const clearTasks = document.getElementById('clearTasks');

  function setTheme(mode){
    app.classList.remove('theme-short','theme-long');
    if(mode==='short') app.classList.add('theme-short');
    if(mode==='long') app.classList.add('theme-long');

    document.documentElement.style.setProperty('--bg', MODES[mode].colors.bg);
    document.documentElement.style.setProperty('--panel', MODES[mode].colors.panel);
  }

  function format(secs){
    const m = Math.floor(secs/60).toString().padStart(2,'0');
    const s = Math.floor(secs%60).toString().padStart(2,'0');
    return `${m}:${s}`;
  }

  function updateTime(){
    timeEl.textContent = format(state.remaining);
  }

  function setMode(mode){
    state.mode = mode;
    tabs.forEach(t=>t.classList.toggle('active', t.dataset.mode===mode));
    state.remaining = MODES[mode].secs;
    updateTime();
    setTheme(mode);
    state.running = false;
    startBtn.textContent = 'START';
    nowTitle.textContent = (mode==='pomo') ? (currentTaskTitle() || 'Time to focus!') : 'Time for a break!';
    nowLine.textContent = '#1';
    if(state.timer){ clearInterval(state.timer); state.timer=null; }
  }

  function startTimer(){
    if(state.running){ // pause
      clearInterval(state.timer);
      state.timer=null;
      state.running=false;
      startBtn.textContent='START';
      return;
    }
    // start
    state.running=true;
    startBtn.textContent='PAUSE';
    state.timer = setInterval(()=>{
      state.remaining--;
      if(state.remaining<=0){
        clearInterval(state.timer); state.timer=null; state.running=false;
        startBtn.textContent='START';
        // auto complete one pomo if mode is pomodoro
        if(state.mode==='pomo'){
          incrementProgressOnCurrent();
        }
        state.remaining = MODES[state.mode].secs;
        updateTime();
      } else {
        updateTime();
      }
    },1000);
  }

  function skip(){
    if(state.running){
      // Treat as complete for pomodoro
      if(state.mode==='pomo'){
        incrementProgressOnCurrent();
      }
      clearInterval(state.timer); state.timer=null; state.running=false;
      state.remaining = MODES[state.mode].secs;
      updateTime();
      startBtn.textContent='START';
    }
  }

  function currentTaskIndex(){
    return state.tasks.findIndex(t=>!t.done);
  }
  function currentTaskTitle(){
    const idx = currentTaskIndex();
    if(idx>-1) return state.tasks[idx].title;
    return '';
  }
  function incrementProgressOnCurrent(){
    const idx = currentTaskIndex();
    if(idx>-1){
      const task = state.tasks[idx];
      task.doneCount = Math.min(task.est, task.doneCount + 1);
      if(task.doneCount>=task.est){ task.done=true; }
      renderTasks();
      checkAllDone();
    }
  }

  tabs.forEach(tab=>{
    tab.addEventListener('click', ()=> setMode(tab.dataset.mode));
  });

  startBtn.addEventListener('click', startTimer);
  skipBtn.addEventListener('click', skip);

  // Add Task flow
  function openForm(){
    addCard.classList.add('show');
    titleInput.value='';
    estVal.textContent='1';
    titleInput.focus();
  }
  function closeForm(){
    addCard.classList.remove('show');
  }
  addBox.addEventListener('click', openForm);
  addBoxBottom.addEventListener('click', openForm);
  cancelAdd.addEventListener('click', closeForm);

  estUp.addEventListener('click', ()=> estVal.textContent = String(Math.min(20, Number(estVal.textContent)+1)));
  estDown.addEventListener('click', ()=> estVal.textContent = String(Math.max(1, Number(estVal.textContent)-1)));

  saveTask.addEventListener('click', ()=>{
    const title = titleInput.value.trim() || 'New Task';
    const est = Number(estVal.textContent);
    state.tasks.push({id: ++state.counter, title, est, doneCount:0, done:false});
    closeForm();
    renderTasks();
    updateSummary();
    nowTitle.textContent = currentTaskTitle() || ((state.mode==='pomo')?'Time to focus!':'Time for a break!');
  });

  function renderTasks(){
    list.innerHTML='';
    state.tasks.forEach((t,idx)=>{
      const item = document.createElement('div');
      item.className = 'task' + (idx===currentTaskIndex() ? ' current' : '') + (t.done?' done':'');
      item.innerHTML = `
        <div class="left">
          <div class="check btn" data-id="${t.id}">
            <img src="__PLACEHOLDER_ASSETS_BASE_DIR__/016.png" width="14" height="14" alt="check">
          </div>
          <div class="tname" ${t.done?'style="text-decoration:line-through; opacity:.6;"':''}>${t.title}</div>
        </div>
        <div class="right">
          <div class="ratio">${t.doneCount} / ${t.est}</div>
          <button class="icon-btn btn tiny" title="More"><img class="icon" src="__PLACEHOLDER_ASSETS_BASE_DIR__/003.png" width="16" height="16" alt="more"></button>
        </div>`;
      list.appendChild(item);
    });

    // attach events
    list.querySelectorAll('.check').forEach(chk=>{
      chk.addEventListener('click', ()=>{
        const id = Number(chk.getAttribute('data-id'));
        const task = state.tasks.find(x=>x.id===id);
        if(task){
          task.done = !task.done;
          if(task.done){ task.doneCount = task.est; } else { task.doneCount = 0; }
          renderTasks();
          updateSummary();
          nowTitle.textContent = currentTaskTitle() || ((state.mode==='pomo')?'Time to focus!':'Time for a break!');
          checkAllDone();
        }
      });
    });
  }

  function updateSummary(){
    const total = state.tasks.reduce((a,b)=>a + b.est, 0);
    const done = state.tasks.reduce((a,b)=>a + b.doneCount, 0);
    const remaining = total - done;
    if(total===0){
      summary.style.display='none';
      pomoCount.textContent='0 / 0';
      finishAt.textContent='--:--';
      return;
    }
    summary.style.display='';
    pomoCount.textContent = `${done} / ${total}`;
    const now = new Date();
    const addMinutes = remaining * 25;
    const finish = new Date(now.getTime() + addMinutes*60000);
    const hh = finish.getHours().toString().padStart(2,'0');
    const mm = finish.getMinutes().toString().padStart(2,'0');
    finishAt.textContent = `${hh}:${mm}`;
    // After updating, refresh "now" line
    const idx = currentTaskIndex();
    nowLine.textContent = idx>-1 ? `#${idx+1}` : '#1';
  }

  function checkAllDone(){
    const any = state.tasks.length>0;
    const allDone = any && state.tasks.every(t=>t.done);
    if(allDone){
      showToast();
      throwConfetti();
    }
  }

  function showToast(){
    toast.classList.add('show');
  }
  clearTasks.addEventListener('click', ()=>{
    state.tasks = [];
    renderTasks(); updateSummary();
    toast.classList.remove('show');
  });

  // Confetti generator
  function throwConfetti(){
    confettiArea.innerHTML='';
    const colors = ['#ff4757','#ffa502','#2ed573','#1e90ff','#3742fa','#e84393','#f9ca24','#7ed6df'];
    for(let i=0;i<70;i++){
      const d = document.createElement('div');
      d.className='confetti';
      d.style.left = (Math.random()*90 + 5) + '%';
      d.style.background = colors[i%colors.length];
      d.style.animation = `drop ${1200 + Math.random()*1000}ms ease-out ${Math.random()*200}ms forwards`;
      confettiArea.appendChild(d);
    }
    // remove after a while
    setTimeout(()=>{ confettiArea.innerHTML=''; }, 2500);
  }

  // Toast hidden on outside click
  document.addEventListener('click', (e)=>{
    if(e.target===toast) toast.classList.remove('show');
  });

  // Initialize
  setTheme('pomo');
  updateTime();
})();
</script>
</body>
</html>
